def parse_equations(eq_text):
    lines = eq_text.strip().split('\n')
    n = len(lines)
    A = np.zeros((n, n))
    b = np.zeros(n)

    for i, line in enumerate(lines):
        # Split by '=' to get left and right side
        left, right = line.split(' = ')
        b[i] = int(right)

        # Parse each term like "11*x_0" or "-89*x_1"
        terms = re.findall(r'(-?\d+)\*x_(\d+)', left)
        for coef, var_idx in terms:
            A[i, int(var_idx)] = int(coef)

    return A, b

A, b = parse_equations(equations)
x = np.linalg.solve(A, b)

# Round to integers and convert to characters
flag_chars = [chr(round(c)) for c in x]
flag = 'pascalCTF{' + ''.join(flag_chars) + '}'
print(flag)
